import java.util.concurrent.*;import java.util.concurrent.locks.*;
class Wallet{int id,balance=100;ReentrantLock lock=new ReentrantLock();Wallet(int i){id=i;}}
public class TokenCounter{int[]buf=new int[5];int count,in,out,max;
 synchronized void put(int v)throws InterruptedException{while(count==5)wait();buf[in]=v;in=(in+1)%5;count++;max=Math.max(max,count);notifyAll();}
 synchronized int take()throws InterruptedException{while(count==0)wait();int v=buf[out];out=(out+1)%5;count--;notifyAll();return v;}
 static void safeTransfer(Wallet a,Wallet b,int amount){Wallet first=a.id<b.id?a:b,second=a.id<b.id?b:a;first.lock.lock();try{second.lock.lock();try{a.balance-=amount;b.balance+=amount;}finally{second.lock.unlock();}}finally{first.lock.unlock();}}
 static void deadlockDemo()throws Exception{Wallet a=new Wallet(1),b=new Wallet(2);CountDownLatch ready=new CountDownLatch(2),go=new CountDownLatch(1);Thread t1=new Thread(()->transferUnsafe(a,b,ready,go)),t2=new Thread(()->transferUnsafe(b,a,ready,go));t1.setDaemon(true);t2.setDaemon(true);t1.start();t2.start();ready.await();go.countDown();t1.join(100);t2.join(100);System.out.println("Unsafe transfer deadlock observed="+(t1.isAlive()||t2.isAlive()));Wallet c=new Wallet(3),d=new Wallet(4);Thread p=new Thread(()->safeTransfer(c,d,5)),q=new Thread(()->safeTransfer(d,c,5));p.start();q.start();p.join();q.join();System.out.println("Ordered-lock transfers completed=true");}
 static void transferUnsafe(Wallet a,Wallet b,CountDownLatch r,CountDownLatch g){a.lock.lock();try{r.countDown();g.await();b.lock.lock();try{a.balance--;b.balance++;}finally{b.lock.unlock();}}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{a.lock.unlock();}}
 public static void main(String[]x)throws Exception{deadlockDemo();TokenCounter c=new TokenCounter();int[]sum={0,0};Thread cook=new Thread(()->{try{for(int i=1;i<=20;i++)c.put(i);}catch(InterruptedException e){Thread.currentThread().interrupt();}});Thread[]s=new Thread[2];for(int i=0;i<2;i++){final int k=i;s[i]=new Thread(()->{try{for(int j=0;j<10;j++)sum[k]+=c.take();}catch(InterruptedException e){Thread.currentThread().interrupt();}});}cook.start();for(Thread t:s)t.start();cook.join();for(Thread t:s)t.join();System.out.println("Sum of tokens collected: "+(sum[0]+sum[1])+" (expected 210)");System.out.println("Maximum counter occupancy: "+c.max+" / 5");}}
